head.script:
scwin.onpageload = function() {};
scwin.onpageunload = function() {};
scwin.__checkProperty = function() {
    return WebSquare.wUnit.getJq("#txta").attr('name');
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. 샘플파일 실행 후 개발자도구(F12)에서 textArea부분을 inspect하여 name 태그가 있는지를 확인한다.
    //1. After running the sample file, inspect the textArea part of the developer tool (F12) to see if there is a name tag.
    //Verify 1. name='test'값이 랜더링되어 보여진다.
    //1. The name = 'test' value is rendered.
    WebSquare.wUnit.addCommand("assert", "scwin.__checkProperty() == 'test'", "true");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 22-Feb-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
